#!/bin/bash

module load gcc/gcc12

#for i in {0.25,0.225,0.21}; do
for i in {0.7,0.69,0.68,0.67,0.66,0.64,0.63}; do
# setup result directory
RESULT_DIR="rho=${i}_eps=0.002_Dp_phase_RESULT/"
#RESULT_DIR="rho=0.65_eps=${i}_Dp_phase_RESULT/"

mkdir $RESULT_DIR

#input file name
INPUT_FILE="${pwd}input${i}.dat"

#file at which output is redirected
OUT_FILE="${pwd}output${i}.dat"

#restart file (generated by running this script without a restart)i
RESTART_FILE="IC_FILES/restart3"

IC_FILE="IC_rho_Dp_phase2/"
	
#D1_p_star=$(bc <<<"-0.3577")
#D1_p_star=$(bc <<<"-0.361161617649 ")
#D1_p_star=$(bc <<<"-1.03848")
D1_p_star=$(bc <<<"-2.0")
#D1_p_star=$(bc <<<"-1.57637605865")
#D1_p_star=$(bc <<<"-0.358290028375 ")

Lx=8.0

#generate a new input file  

# output problem parameters to input file 
#**************** Problem Parameters *************************
printf "D2 = 0.2\n" > $INPUT_FILE
printf "beta=8.0\n" >> $INPUT_FILE
printf "alpha = 10\n" >> $INPUT_FILE
printf "D1_star = 0.5\n" >> $INPUT_FILE
printf "D1_p_star = ${D1_p_star}\n" >>  $INPUT_FILE
printf "D_inf_0 = 0.1\n" >> $INPUT_FILE
printf "Lu = 1.5\n" >>  $INPUT_FILE
printf "Lx = ${Lx}\n" >>  $INPUT_FILE
	
#**************** kinetic parameters ***********************
printf "a = 0.3\n" >>  $INPUT_FILE
printf "L = 6.0\n" >>  $INPUT_FILE
printf "K = 0.3\n" >>  $INPUT_FILE
printf "lambda = 4.5\n" >>  $INPUT_FILE
printf "m=${i}\n" >>  $INPUT_FILE
#printf "m=0.65\n" >>  $INPUT_FILE
printf "epsilon = 2e-3\n" >>  $INPUT_FILE
#printf "epsilon = ${i}\n" >>  $INPUT_FILE

#****************** numerical parameters **********************
printf "Nu_density = 600\n" >>  $INPUT_FILE
printf "Nu_helm = 1\n" >>  $INPUT_FILE
printf "Nx = 50\n" >>  $INPUT_FILE
printf "rho_eval = ${Lx}\n" >> $INPUT_FILE

#mpirun -np 8./steady_solve $INPUT_FILE $RESULT_DIR --restart-file $RESTART_FILE > $OUT_FILE #with restart
mpirun -np 8 ./steady_solve $INPUT_FILE $RESULT_DIR --IC-file $IC_FILE > $OUT_FILE &	#without restart
#mpirun -np 8 ./steady_solve $INPUT_FILE $RESULT_DIR > $OUT_FILE &
#mpirun ./steady_solve $INPUT_FILE $RESULT_DIR > $OUT_FILE	#without restart


done

